import { useMutation, type UseMutationOptions } from "@tanstack/react-query";
import { createReward } from "../handlers/createReward";
import type { ApiError } from "../runtime/client";
import type { CreateGlobalRewardRequest } from "../types/CreateGlobalRewardRequest";

type Data = Awaited<ReturnType<typeof createReward>>;
type Vars = CreateGlobalRewardRequest;

export function useCreateReward(
  options?: Omit<UseMutationOptions<Data, ApiError, Vars>, "mutationFn">,
) {
  return useMutation<Data, ApiError, Vars>({
    mutationFn: (vars) => createReward(vars),
    ...options,
  });
}
